-- ATHLOS: FIRST INSTALLATION ONLY.
-- Run in the dedicated athlete-monitoring-system Supabase project.
-- Existing installations should apply only their outstanding migrations.
-- Generated by npm run db:bundle; no passwords or API keys are included.
-- One transaction: any error rolls back this installation.

begin;

-- 202611030001_initial.sql
create extension if not exists pgcrypto;
create type public.app_role as enum ('administrator','coach','medical','athlete');
create type public.attendance_status as enum ('pending','attended','rest','rehabilitation','absent','not_participating');
create table public.organizations(id uuid primary key default gen_random_uuid(),name text not null,timezone text not null default 'Asia/Shanghai',settings jsonb not null default '{}');
create table public.user_profiles(id uuid primary key references auth.users(id),organization_id uuid not null references public.organizations,role public.app_role not null,name text not null,locale text not null default 'zh' check(locale in ('zh','ja','en')));
create table public.teams(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations,name text not null);
create table public.athletes(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations,user_id uuid unique references public.user_profiles,name text not null,number integer not null,position text not null);
create table public.team_memberships(athlete_id uuid references public.athletes,team_id uuid references public.teams,primary key(athlete_id,team_id));
create table public.staff_permissions(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.user_profiles,team_id uuid references public.teams,athlete_id uuid references public.athletes,check((team_id is null)<>(athlete_id is null)),unique(user_id,team_id),unique(user_id,athlete_id));
create table public.sessions(id uuid primary key default gen_random_uuid(),team_id uuid not null references public.teams,code text not null,date date not null,start_time time not null,end_time time not null,type text not null check(type in ('Field','Gym','Rehabilitation','Match','Other')),duration integer not null check(duration between 0 and 600),check(end_time>start_time),unique(team_id,date,code));
create table public.athlete_sessions(athlete_id uuid references public.athletes,session_id uuid references public.sessions,status public.attendance_status not null default 'pending',minutes integer not null check(minutes between 0 and 600),rpe numeric check(rpe between 0 and 10),updated_at timestamptz not null default now(),primary key(athlete_id,session_id),check(status not in ('attended','rehabilitation') or rpe is not null));
create table public.wellness_responses(id uuid primary key default gen_random_uuid(),athlete_id uuid not null references public.athletes,date date not null,sleep_hours numeric not null check(sleep_hours between 0 and 24),sleep_quality integer not null check(sleep_quality between 0 and 10),fatigue integer not null check(fatigue between 0 and 10),soreness integer not null check(soreness between 0 and 10),stress integer not null check(stress between 0 and 10),appetite integer not null check(appetite between 0 and 10),weight numeric not null check(weight between 20 and 300),comment text not null default '' check(length(comment)<=2000),updated_at timestamptz not null default now(),unique(athlete_id,date));
create table public.pain_records(id uuid primary key default gen_random_uuid(),athlete_id uuid not null references public.athletes,date date not null,body_part text not null check(length(body_part) between 1 and 100),severity integer not null check(severity between 0 and 10));
create table public.medical_notes(id uuid primary key default gen_random_uuid(),athlete_id uuid not null references public.athletes,author_id uuid not null references public.user_profiles default auth.uid(),created_at timestamptz not null default now(),note text not null check(length(note) between 1 and 5000));
create table public.alert_rules(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations,metric text not null,threshold numeric not null,enabled boolean not null default true);
create table public.alert_events(id uuid primary key default gen_random_uuid(),athlete_id uuid not null references public.athletes,rule_id uuid references public.alert_rules,date date not null,measured numeric not null,threshold numeric not null,created_at timestamptz not null default now());
create table public.audit_logs(id bigint generated always as identity primary key,organization_id uuid references public.organizations,actor_id uuid references auth.users,table_name text not null,record_key jsonb not null,operation text not null,created_at timestamptz not null default now());
-- GPS imports retain the same athlete/session identities. No raw GPS or medical values in audit logs.
create table public.gps_records(id uuid primary key default gen_random_uuid(),athlete_id uuid not null,session_id uuid not null,source text not null default 'catapult_openfield',external_id text not null,metrics jsonb not null,imported_at timestamptz not null default now(),foreign key(athlete_id,session_id) references public.athlete_sessions,unique(source,external_id));
create index on public.wellness_responses(date,athlete_id);
create index on public.sessions(date,team_id);
create index on public.pain_records(athlete_id,date);
create index on public.staff_permissions(user_id);
create index on public.team_memberships(team_id);
create function public.my_org() returns uuid language sql stable security definer set search_path=public as $$select organization_id from user_profiles where id=auth.uid()$$;
create function public.my_role() returns public.app_role language sql stable security definer set search_path=public as $$select role from user_profiles where id=auth.uid()$$;
create function public.admin_org(org uuid) returns boolean language sql stable security definer set search_path=public as $$select coalesce(public.my_role()='administrator' and public.my_org()=org,false)$$;
create function public.owns_athlete(a uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from athletes where id=a and user_id=auth.uid() and organization_id=public.my_org())$$;
create function public.coaches_team(t uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from teams where id=t and organization_id=public.my_org() and (public.my_role()='administrator' or public.my_role()='coach' and exists(select 1 from staff_permissions p where p.user_id=auth.uid() and p.team_id=t)))$$;
create function public.can_read_athlete(a uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from athletes x where x.id=a and x.organization_id=public.my_org() and (public.admin_org(x.organization_id) or public.owns_athlete(a) or public.my_role()='coach' and exists(select 1 from team_memberships m where m.athlete_id=a and public.coaches_team(m.team_id)) or public.my_role()='medical' and exists(select 1 from staff_permissions p where p.user_id=auth.uid() and (p.athlete_id=a or p.team_id in(select team_id from team_memberships where athlete_id=a)))))$$;
create function public.can_read_medical(a uuid) returns boolean language sql stable security definer set search_path=public as $$select public.can_read_athlete(a) and (public.my_role() in ('administrator','medical') or public.owns_athlete(a))$$;
create function public.can_write_athlete(a uuid) returns boolean language sql stable security definer set search_path=public as $$select public.owns_athlete(a) or exists(select 1 from athletes where id=a and public.admin_org(organization_id))$$;
create function public.valid_assignment(a uuid,s uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from sessions x join teams t on t.id=x.team_id join team_memberships m on m.team_id=t.id join athletes p on p.id=m.athlete_id where x.id=s and p.id=a and p.organization_id=t.organization_id)$$;
create function public.can_read_session(s uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from sessions where id=s and public.coaches_team(team_id)) or exists(select 1 from athlete_sessions x where x.session_id=s and public.owns_athlete(x.athlete_id))$$;
-- All application tables deny anonymous access and default to no access without a policy.
do $$declare t text;begin foreach t in array array['organizations','user_profiles','teams','athletes','team_memberships','staff_permissions','sessions','athlete_sessions','wellness_responses','pain_records','medical_notes','alert_rules','alert_events','audit_logs','gps_records'] loop execute format('alter table public.%I enable row level security',t);end loop;end$$;
create policy org_read on public.organizations for select to authenticated using(id=public.my_org());
create policy org_admin on public.organizations for update to authenticated using(public.admin_org(id)) with check(public.admin_org(id));
create policy profile_read on public.user_profiles for select to authenticated using(id=auth.uid() or public.admin_org(organization_id));
create policy profile_admin on public.user_profiles for all to authenticated using(public.admin_org(organization_id)) with check(public.admin_org(organization_id));
create policy team_read on public.teams for select to authenticated using(organization_id=public.my_org() and (public.coaches_team(id) or exists(select 1 from public.team_memberships m where m.team_id=id and public.can_read_athlete(m.athlete_id))));
create policy team_admin on public.teams for all to authenticated using(public.admin_org(organization_id)) with check(public.admin_org(organization_id));
create policy athlete_read on public.athletes for select to authenticated using(public.can_read_athlete(id));
create policy athlete_admin on public.athletes for all to authenticated using(public.admin_org(organization_id)) with check(public.admin_org(organization_id));
create policy membership_read on public.team_memberships for select to authenticated using(public.can_read_athlete(athlete_id));
create policy membership_admin on public.team_memberships for all to authenticated using(exists(select 1 from public.athletes a where a.id=athlete_id and public.admin_org(a.organization_id))) with check(exists(select 1 from public.athletes a join public.teams t on t.organization_id=a.organization_id where a.id=athlete_id and t.id=team_id and public.admin_org(a.organization_id)));
create policy permissions_read on public.staff_permissions for select to authenticated using(user_id=auth.uid() or exists(select 1 from public.user_profiles p where p.id=user_id and public.admin_org(p.organization_id)));
create policy permissions_admin on public.staff_permissions for all to authenticated using(exists(select 1 from public.user_profiles p where p.id=user_id and public.admin_org(p.organization_id))) with check(exists(select 1 from public.user_profiles p where p.id=user_id and public.admin_org(p.organization_id) and (team_id is null or exists(select 1 from public.teams t where t.id=team_id and t.organization_id=p.organization_id)) and (athlete_id is null or exists(select 1 from public.athletes a where a.id=athlete_id and a.organization_id=p.organization_id))));
create policy session_read on public.sessions for select to authenticated using(public.can_read_session(id));
create policy session_staff on public.sessions for all to authenticated using(public.coaches_team(team_id)) with check(public.coaches_team(team_id));
create policy entry_read on public.athlete_sessions for select to authenticated using(public.can_read_athlete(athlete_id));
create policy entry_staff on public.athlete_sessions for all to authenticated using(exists(select 1 from public.sessions s where s.id=session_id and public.coaches_team(s.team_id))) with check(public.valid_assignment(athlete_id,session_id) and exists(select 1 from public.sessions s where s.id=session_id and public.coaches_team(s.team_id)));
create policy entry_athlete_update on public.athlete_sessions for update to authenticated using(public.owns_athlete(athlete_id)) with check(public.owns_athlete(athlete_id) and public.valid_assignment(athlete_id,session_id));
create policy wellness_read on public.wellness_responses for select to authenticated using(public.can_read_athlete(athlete_id));
create policy wellness_write on public.wellness_responses for all to authenticated using(public.can_write_athlete(athlete_id)) with check(public.can_write_athlete(athlete_id));
create policy pain_read on public.pain_records for select to authenticated using(public.can_read_medical(athlete_id));
create policy pain_write on public.pain_records for all to authenticated using(public.can_write_athlete(athlete_id)) with check(public.can_write_athlete(athlete_id));
create policy medical_read on public.medical_notes for select to authenticated using(public.can_read_medical(athlete_id) and public.my_role() in ('administrator','medical'));
create policy medical_write on public.medical_notes for insert to authenticated with check(public.can_read_medical(athlete_id) and public.my_role() in ('administrator','medical') and author_id=auth.uid());
create policy rules_read on public.alert_rules for select to authenticated using(organization_id=public.my_org());
create policy rules_admin on public.alert_rules for all to authenticated using(public.admin_org(organization_id)) with check(public.admin_org(organization_id));
create policy events_read on public.alert_events for select to authenticated using(public.can_read_medical(athlete_id));
create policy events_admin on public.alert_events for all to authenticated using(exists(select 1 from public.athletes a where a.id=athlete_id and public.admin_org(a.organization_id))) with check(exists(select 1 from public.athletes a where a.id=athlete_id and public.admin_org(a.organization_id)));
create policy audit_admin on public.audit_logs for select to authenticated using(public.admin_org(organization_id));
create policy gps_read on public.gps_records for select to authenticated using(public.can_read_athlete(athlete_id));
create policy gps_staff on public.gps_records for all to authenticated using(public.can_read_athlete(athlete_id) and public.my_role() in ('administrator','coach')) with check(public.valid_assignment(athlete_id,session_id) and exists(select 1 from public.sessions s where s.id=session_id and public.coaches_team(s.team_id)));
create view public.training_load_records with (security_invoker=true) as select athlete_id,session_id,status,minutes,rpe,case when status in ('attended','rehabilitation') then minutes*rpe when status='pending' then null else 0 end as load from public.athlete_sessions;
create view public.daily_training_load with (security_invoker=true) as select a.athlete_id,s.date,case when bool_or(a.status='pending') then null else sum(case when a.status in ('attended','rehabilitation') then a.minutes*a.rpe else 0 end) end as total_load from public.athlete_sessions a join public.sessions s on s.id=a.session_id group by a.athlete_id,s.date;
-- Prevent athlete assignment/identity changes; allow athletes to update only their own response fields.
create function public.guard_entry_identity() returns trigger language plpgsql set search_path=public as $$begin if new.athlete_id<>old.athlete_id or new.session_id<>old.session_id then raise exception 'Assignment identity is immutable';end if;new.updated_at=now();return new;end$$;
create trigger entry_identity before update on public.athlete_sessions for each row execute function public.guard_entry_identity();
create function public.audit_change() returns trigger language plpgsql security definer set search_path=public as $$declare row_data jsonb;org uuid;begin row_data=case when tg_op='DELETE' then to_jsonb(old) else to_jsonb(new) end;org=public.my_org();insert into public.audit_logs(organization_id,actor_id,table_name,record_key,operation) values(org,auth.uid(),tg_table_name,jsonb_strip_nulls(jsonb_build_object('id',row_data->'id','athlete_id',row_data->'athlete_id','session_id',row_data->'session_id')),tg_op);return coalesce(new,old);end$$;
do $$declare t text;begin foreach t in array array['organizations','user_profiles','teams','athletes','team_memberships','staff_permissions','sessions','athlete_sessions','wellness_responses','pain_records','medical_notes','alert_rules','alert_events','gps_records'] loop execute format('create trigger audit_row after insert or update or delete on public.%I for each row execute function public.audit_change()',t);end loop;end$$;
-- Both writes are atomic, use caller RLS; no service role bypass.
create function public.save_wellness(payload jsonb) returns void language plpgsql security invoker set search_path=public as $$declare a uuid=(payload->>'athlete_id')::uuid;d date=(payload->>'date')::date;p jsonb;begin
insert into public.wellness_responses(athlete_id,date,sleep_hours,sleep_quality,fatigue,soreness,stress,appetite,weight,comment) values(a,d,(payload->>'sleep_hours')::numeric,(payload->>'sleep_quality')::int,(payload->>'fatigue')::int,(payload->>'soreness')::int,(payload->>'stress')::int,(payload->>'appetite')::int,(payload->>'weight')::numeric,coalesce(payload->>'comment','')) on conflict(athlete_id,date) do update set sleep_hours=excluded.sleep_hours,sleep_quality=excluded.sleep_quality,fatigue=excluded.fatigue,soreness=excluded.soreness,stress=excluded.stress,appetite=excluded.appetite,weight=excluded.weight,comment=excluded.comment,updated_at=now();
delete from public.pain_records where athlete_id=a and date=d;
for p in select * from jsonb_array_elements(coalesce(payload->'pain','[]')) loop insert into public.pain_records(athlete_id,date,body_part,severity) values(a,d,p->>'body_part',(p->>'severity')::int);end loop;end$$;
create function public.create_session(payload jsonb) returns uuid language plpgsql security invoker set search_path=public as $$declare sid uuid;a text;begin
insert into public.sessions(team_id,code,date,start_time,end_time,type,duration) values((payload->>'team_id')::uuid,payload->>'code',(payload->>'date')::date,(payload->>'start_time')::time,(payload->>'end_time')::time,payload->>'type',(payload->>'duration')::int) returning id into sid;
for a in select jsonb_array_elements_text(payload->'athlete_ids') loop insert into public.athlete_sessions(athlete_id,session_id,minutes) values(a::uuid,sid,(payload->>'duration')::int);end loop;return sid;end$$;
revoke all on all tables in schema public from anon;
revoke execute on all functions in schema public from public;
grant execute on all functions in schema public to authenticated;
grant select,insert,update,delete on all tables in schema public to authenticated;
revoke insert,update,delete on public.audit_logs from authenticated;
grant usage,select on all sequences in schema public to authenticated;

-- 202611030002_integrity.sql
create function public.guard_org_links() returns trigger language plpgsql security definer set search_path=public as $$begin
if tg_op='UPDATE' and new.organization_id<>old.organization_id then raise exception 'Organization identity is immutable';end if;
if tg_table_name='athletes' then
 if new.user_id is not null then
 if not exists(select 1 from public.user_profiles where id=new.user_id and organization_id=new.organization_id and role='athlete') then raise exception 'Athlete account must belong to the same organization and athlete role';end if;
 end if;
end if;
if tg_table_name='user_profiles' then
 if new.role<>'athlete' and exists(select 1 from public.athletes where user_id=new.id) then raise exception 'Unlink athlete account before changing role';end if;
end if;
return new;end$$;
create trigger athlete_org_link before insert or update on public.athletes for each row execute function public.guard_org_links();
create trigger profile_org_link before insert or update on public.user_profiles for each row execute function public.guard_org_links();
create function public.guard_session_team() returns trigger language plpgsql set search_path=public as $$begin if new.team_id<>old.team_id then raise exception 'Session team is immutable; create a new session';end if;return new;end$$;
create trigger session_team_identity before update on public.sessions for each row execute function public.guard_session_team();
create function public.save_athlete(payload jsonb) returns uuid language plpgsql security invoker set search_path=public as $$declare aid uuid;tid uuid=(payload->>'team_id')::uuid;begin
if payload->>'id' is null then insert into public.athletes(organization_id,user_id,name,number,position) values(public.my_org(),nullif(payload->>'user_id','')::uuid,payload->>'name',(payload->>'number')::int,payload->>'position') returning id into aid;
else aid=(payload->>'id')::uuid;update public.athletes set user_id=nullif(payload->>'user_id','')::uuid,name=payload->>'name',number=(payload->>'number')::int,position=payload->>'position' where id=aid;end if;
insert into public.team_memberships(athlete_id,team_id) values(aid,tid) on conflict do nothing;return aid;end$$;
revoke execute on function public.guard_org_links(),public.guard_session_team(),public.save_athlete(jsonb) from public;
grant execute on function public.save_athlete(jsonb) to authenticated;

-- 202611030003_session_edit.sql
create function public.edit_session(payload jsonb) returns uuid language plpgsql security invoker set search_path=public as $$declare sid uuid=(payload->>'id')::uuid;a text;begin
-- Lock protects submitted responses while changing the roster.
perform 1 from public.sessions where id=sid for update;
if not found then raise exception 'Session unavailable';end if;
perform 1 from public.athlete_sessions where session_id=sid for update;
if exists(select 1 from public.athlete_sessions e where e.session_id=sid and e.status<>'pending' and not (payload->'athlete_ids' ? e.athlete_id::text)) then raise exception 'Cannot remove an athlete with a submitted response';end if;
update public.sessions set code=payload->>'code',date=(payload->>'date')::date,type=payload->>'type',start_time=(payload->>'start_time')::time,end_time=(payload->>'end_time')::time,duration=(payload->>'duration')::int where id=sid and team_id=(payload->>'team_id')::uuid;
if not found then raise exception 'Session update denied';end if;
delete from public.athlete_sessions where session_id=sid and status='pending' and not (payload->'athlete_ids' ? athlete_id::text);
for a in select jsonb_array_elements_text(payload->'athlete_ids') loop insert into public.athlete_sessions(athlete_id,session_id,minutes) values(a::uuid,sid,(payload->>'duration')::int) on conflict(athlete_id,session_id) do update set minutes=case when athlete_sessions.status='pending' then excluded.minutes else athlete_sessions.minutes end;end loop;
return sid;end$$;
revoke execute on function public.edit_session(jsonb) from public;
grant execute on function public.edit_session(jsonb) to authenticated;

-- 202611030004_bulk_import.sql
-- The entire batch is one transaction. SECURITY INVOKER preserves caller RLS.
-- The role gate also blocks athletes who may update their own individual records.
create function public.bulk_import_records(import_kind text, rows jsonb, overwrite_existing boolean default false)
returns jsonb language plpgsql security invoker set search_path=public as $$
declare item jsonb;a uuid;sid uuid;existing_status public.attendance_status;changed uuid;saved integer=0;skipped integer=0;actor_role public.app_role;
begin
actor_role=public.my_role();
if actor_role is null or actor_role not in ('administrator','coach') then raise exception 'Bulk import requires staff role' using errcode='42501';end if;
if import_kind is null or rows is null or import_kind not in ('rpe','wellness') or jsonb_typeof(rows)<>'array' then raise exception 'Invalid batch';end if;
if jsonb_array_length(rows) not between 1 and 500 then raise exception 'Batch must contain 1 to 500 rows';end if;
if import_kind='wellness' and actor_role<>'administrator' then raise exception 'Wellness proxy import requires administrator' using errcode='42501';end if;
if exists(select 1 from jsonb_array_elements(rows) r group by r->>'athlete_id',case when import_kind='rpe' then r->>'session_id' else r->>'date' end having count(*)>1) then raise exception 'Duplicate batch rows';end if;
for item in select * from jsonb_array_elements(rows) loop
 a=(item->>'athlete_id')::uuid;
 if import_kind='rpe' then
  sid=(item->>'session_id')::uuid;
  if not exists(select 1 from public.sessions s where s.id=sid and s.team_id=(item->>'team_id')::uuid and s.date=(item->>'date')::date and public.coaches_team(s.team_id)) then raise exception 'Session or staff permission unavailable' using errcode='42501';end if;
  if not public.valid_assignment(a,sid) then raise exception 'Athlete is not a valid session assignment';end if;
  select status into existing_status from public.athlete_sessions where athlete_id=a and session_id=sid for update;
  if not found then raise exception 'Assigned athlete response unavailable' using errcode='42501';end if;
  -- Direct RPC callers must satisfy the same validation as the HTTP endpoint.
  if (item->>'status') is null or (item->>'status') not in ('attended','rehabilitation','rest','absent','not_participating') or (item->>'minutes') is null then raise exception 'Invalid attendance';end if;
  if (item->>'status') in ('rest','absent','not_participating') and ((item->>'minutes')::integer<>0 or item->>'rpe' is not null) then raise exception 'Non-participation requires zero minutes and no RPE';end if;
  if (item->>'minutes')::integer not between 0 and 600 or (item->>'rpe')::numeric not between 0 and 10 then raise exception 'RPE or minutes out of range';end if;
  if existing_status<>'pending' and not coalesce(overwrite_existing,false) then skipped=skipped+1;continue;end if;
  update public.athlete_sessions set status=(item->>'status')::public.attendance_status,minutes=(item->>'minutes')::integer,rpe=(item->>'rpe')::numeric where athlete_id=a and session_id=sid;
  if not found then raise exception 'Response update denied' using errcode='42501';end if;
  saved=saved+1;
 else
  if not public.can_write_athlete(a) then raise exception 'Athlete permission denied' using errcode='42501';end if;
  changed=null;
  insert into public.wellness_responses(athlete_id,date,sleep_hours,sleep_quality,fatigue,soreness,stress,appetite,weight,comment)
  values(a,(item->>'date')::date,(item->>'sleep_hours')::numeric,(item->>'sleep_quality')::int,(item->>'fatigue')::int,(item->>'soreness')::int,(item->>'stress')::int,(item->>'appetite')::int,(item->>'weight')::numeric,coalesce(item->>'comment',''))
  on conflict(athlete_id,date) do update set sleep_hours=excluded.sleep_hours,sleep_quality=excluded.sleep_quality,fatigue=excluded.fatigue,soreness=excluded.soreness,stress=excluded.stress,appetite=excluded.appetite,weight=excluded.weight,comment=excluded.comment,updated_at=now() where coalesce(overwrite_existing,false) returning id into changed;
  -- Medical pain records are deliberately not replaced by a daily wellness import.
  if changed is null then skipped=skipped+1;else saved=saved+1;end if;
 end if;
end loop;
return jsonb_build_object('saved',saved,'skipped',skipped);
end$$;
revoke execute on function public.bulk_import_records(text,jsonb,boolean) from public,anon;
grant execute on function public.bulk_import_records(text,jsonb,boolean) to authenticated;

-- 202611030005_validation.sql
-- A shared athlete membership must not expose another team's session responses.
drop policy entry_read on public.athlete_sessions;
create policy entry_read on public.athlete_sessions for select to authenticated using(
 public.owns_athlete(athlete_id)
 or exists(select 1 from public.athletes a where a.id=athlete_id and public.admin_org(a.organization_id))
 or (public.my_role()='coach' and exists(select 1 from public.sessions s where s.id=session_id and public.coaches_team(s.team_id)))
 or (public.my_role()='medical' and public.can_read_medical(athlete_id))
);
drop policy gps_read on public.gps_records;
create policy gps_read on public.gps_records for select to authenticated using(
 public.owns_athlete(athlete_id)
 or exists(select 1 from public.athletes a where a.id=athlete_id and public.admin_org(a.organization_id))
 or (public.my_role()='coach' and exists(select 1 from public.sessions s where s.id=session_id and public.coaches_team(s.team_id)))
);
-- Authenticated clients can call PostgREST directly, so also enforce configured scales at DB boundary.
create function public.validate_wellness_scales() returns trigger language plpgsql security definer set search_path=public as $$
declare config jsonb;metric text;value integer;lo integer;hi integer;
begin
 select o.settings into config from public.athletes a join public.organizations o on o.id=a.organization_id where a.id=new.athlete_id;
 foreach metric in array array['sleep_quality','fatigue','soreness','stress','appetite'] loop
  lo=coalesce((config->'scales'->metric->>'min')::integer,1);
  hi=coalesce((config->'scales'->metric->>'max')::integer,5);
  value=(to_jsonb(new)->>metric)::integer;
  if value<lo or value>hi then raise check_violation using message=metric||' outside configured scale';end if;
 end loop;
 new.updated_at=now();return new;
end$$;
create trigger wellness_configured_scales before insert or update on public.wellness_responses for each row execute function public.validate_wellness_scales();
revoke execute on function public.validate_wellness_scales() from public;
create function public.validate_staff_scope() returns trigger language plpgsql security definer set search_path=public as $$declare r public.app_role;begin
select role into r from public.user_profiles where id=new.user_id;
if r not in ('coach','medical') or r is null or (r='coach' and new.team_id is null) then raise check_violation using message='Invalid staff permission scope';end if;
return new;end$$;
create trigger staff_scope before insert or update on public.staff_permissions for each row execute function public.validate_staff_scope();
revoke execute on function public.validate_staff_scope() from public;

-- 202611030006_live_workflow.sql
-- Coaches may record everyday wellness/pain for their assigned team; clinical notes stay restricted.
create function public.coaches_athlete(a uuid) returns boolean language sql stable security definer set search_path=public as $$select public.my_role()='coach' and exists(select 1 from public.team_memberships m where m.athlete_id=a and public.coaches_team(m.team_id))$$;
create or replace function public.can_write_athlete(a uuid) returns boolean language sql stable security definer set search_path=public as $$select public.owns_athlete(a) or public.coaches_athlete(a) or exists(select 1 from public.athletes where id=a and public.admin_org(organization_id))$$;
drop policy pain_read on public.pain_records;
create policy pain_read on public.pain_records for select to authenticated using(public.can_read_medical(athlete_id) or public.coaches_athlete(athlete_id));

create table public.invitations(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations,
 email text not null check(length(email)<=254 and position('@' in email)>1),name text not null check(length(name) between 1 and 100),
 role public.app_role not null,team_id uuid references public.teams,athlete_id uuid references public.athletes,
 token_hash text not null unique,created_by uuid not null references auth.users,created_at timestamptz not null default now(),
 expires_at timestamptz not null default now()+interval '7 days',accepted_by uuid references auth.users,accepted_at timestamptz,revoked_at timestamptz
);
alter table public.invitations enable row level security;
create policy invitations_admin_read on public.invitations for select to authenticated using(public.admin_org(organization_id));
-- Only functions can create/accept/revoke; invitation tokens are never stored as plaintext.
revoke all on public.invitations from anon,authenticated;
grant select on public.invitations to authenticated;
create trigger audit_row after insert or update or delete on public.invitations for each row execute function public.audit_change();

create function public.create_invitation(invite_email text,invite_name text,invite_role public.app_role,invite_team uuid default null,invite_athlete uuid default null) returns jsonb language plpgsql security definer set search_path=public as $$declare org uuid=public.my_org();token text;i uuid;begin
 if not public.admin_org(org) then raise insufficient_privilege;end if;
 if invite_email is null or length(btrim(invite_email))>254 or position('@' in invite_email)<2 or invite_name is null or length(btrim(invite_name)) not between 1 and 100 then raise check_violation using message='Invalid email or name';end if;
 if invite_team is not null and not exists(select 1 from public.teams where id=invite_team and organization_id=org) then raise insufficient_privilege;end if;
 if invite_athlete is not null and not exists(select 1 from public.athletes where id=invite_athlete and organization_id=org and user_id is null) then raise check_violation using message='Select an unlinked athlete in your organization';end if;
 if invite_role='athlete' and invite_athlete is null then raise check_violation using message='Athlete record required';end if;
 if invite_role='coach' and invite_team is null then raise check_violation using message='Coach team required';end if;
 if invite_role='medical' and invite_team is null and invite_athlete is null then raise check_violation using message='Medical scope required';end if;
 token=replace(gen_random_uuid()::text,'-','')||replace(gen_random_uuid()::text,'-','');
 insert into public.invitations(organization_id,email,name,role,team_id,athlete_id,token_hash,created_by) values(org,lower(btrim(invite_email)),btrim(invite_name),invite_role,invite_team,invite_athlete,encode(sha256(convert_to(token,'UTF8')),'hex'),auth.uid()) returning id into i;
 return jsonb_build_object('id',i,'token',token,'expires_in_days',7);
end$$;
create function public.revoke_invitation(invitation_id uuid) returns void language plpgsql security definer set search_path=public as $$begin
 update public.invitations set revoked_at=now() where id=invitation_id and public.admin_org(organization_id) and accepted_at is null;
 if not found then raise insufficient_privilege;end if;
end$$;
create function public.claim_invitation(raw_token text) returns void language plpgsql security definer set search_path=public as $$declare i public.invitations;u uuid=auth.uid();verified_email text;p public.user_profiles;begin
 if u is null then raise insufficient_privilege;end if;
 if raw_token is null or raw_token !~ '^[0-9a-f]{64}$' then raise check_violation using message='Invalid invitation';end if;
 select lower(email) into verified_email from auth.users where id=u and email_confirmed_at is not null;
 if verified_email is null then raise check_violation using message='Verify your email first';end if;
 select * into i from public.invitations where token_hash=encode(sha256(convert_to(raw_token,'UTF8')),'hex') for update;
 if not found or i.email<>verified_email or i.revoked_at is not null or i.expires_at<=now() then raise check_violation using message='Invitation unavailable';end if;
 if i.accepted_at is not null then if i.accepted_by=u then return;else raise check_violation using message='Invitation already accepted';end if;end if;
 select * into p from public.user_profiles where id=u;
 if found then raise check_violation using message='Account already belongs to an organization; contact your administrator';end if;
 insert into public.user_profiles(id,organization_id,role,name) values(u,i.organization_id,i.role,i.name);
 if i.role='athlete' then
  update public.athletes set user_id=u where id=i.athlete_id and organization_id=i.organization_id and user_id is null;
  if not found then raise check_violation using message='Athlete account already linked';end if;
 elsif i.role in ('coach','medical') then
  insert into public.staff_permissions(user_id,team_id,athlete_id) values(u,i.team_id,case when i.team_id is null then i.athlete_id else null end);
 end if;
 update public.invitations set accepted_at=now(),accepted_by=u where id=i.id;
end$$;
create function public.bootstrap_organization(org_name text,team_name text) returns uuid language plpgsql security definer set search_path=public as $$declare u uuid=auth.uid();org uuid;begin
 if u is null or not exists(select 1 from auth.users where id=u and email_confirmed_at is not null) then raise insufficient_privilege;end if;
 -- Lock the Auth row so concurrent first-time requests cannot create duplicate organizations.
 perform 1 from auth.users where id=u for update;
 if exists(select 1 from public.user_profiles where id=u) then raise check_violation using message='Account already configured';end if;
 if org_name is null or team_name is null or length(btrim(org_name)) not between 1 and 100 or length(btrim(team_name)) not between 1 and 100 then raise check_violation using message='Organization and team names required';end if;
 insert into public.organizations(name) values(btrim(org_name)) returning id into org;
 insert into public.user_profiles(id,organization_id,role,name) values(u,org,'administrator','Administrator');
 insert into public.teams(organization_id,name) values(org,btrim(team_name));return org;
end$$;
revoke execute on function public.coaches_athlete(uuid),public.create_invitation(text,text,public.app_role,uuid,uuid),public.revoke_invitation(uuid),public.claim_invitation(text),public.bootstrap_organization(text,text) from public,anon;
grant execute on function public.coaches_athlete(uuid),public.create_invitation(text,text,public.app_role,uuid,uuid),public.revoke_invitation(uuid),public.claim_invitation(text),public.bootstrap_organization(text,text) to authenticated;
create or replace function public.bulk_import_records(import_kind text, rows jsonb, overwrite_existing boolean default false)
returns jsonb language plpgsql security invoker set search_path=public as $$
declare item jsonb;a uuid;sid uuid;existing_status public.attendance_status;changed uuid;saved integer=0;skipped integer=0;actor_role public.app_role;
begin
actor_role=public.my_role();
if actor_role is null or actor_role not in ('administrator','coach') then raise exception 'Bulk import requires staff role' using errcode='42501';end if;
if import_kind is null or rows is null or import_kind not in ('rpe','wellness') or jsonb_typeof(rows)<>'array' then raise exception 'Invalid batch';end if;
if jsonb_array_length(rows) not between 1 and 500 then raise exception 'Batch must contain 1 to 500 rows';end if;

if exists(select 1 from jsonb_array_elements(rows) r group by r->>'athlete_id',case when import_kind='rpe' then r->>'session_id' else r->>'date' end having count(*)>1) then raise exception 'Duplicate batch rows';end if;
for item in select * from jsonb_array_elements(rows) loop
 a=(item->>'athlete_id')::uuid;
 if import_kind='rpe' then
  sid=(item->>'session_id')::uuid;
  if not exists(select 1 from public.sessions s where s.id=sid and s.team_id=(item->>'team_id')::uuid and s.date=(item->>'date')::date and public.coaches_team(s.team_id)) then raise exception 'Session or staff permission unavailable' using errcode='42501';end if;
  if not public.valid_assignment(a,sid) then raise exception 'Athlete is not a valid session assignment';end if;
  select status into existing_status from public.athlete_sessions where athlete_id=a and session_id=sid for update;
  if not found then raise exception 'Assigned athlete response unavailable' using errcode='42501';end if;
  -- Direct RPC callers must satisfy the same validation as the HTTP endpoint.
  if (item->>'status') is null or (item->>'status') not in ('attended','rehabilitation','rest','absent','not_participating') or (item->>'minutes') is null then raise exception 'Invalid attendance';end if;
  if (item->>'status') in ('rest','absent','not_participating') and ((item->>'minutes')::integer<>0 or item->>'rpe' is not null) then raise exception 'Non-participation requires zero minutes and no RPE';end if;
  if (item->>'minutes')::integer not between 0 and 600 or (item->>'rpe')::numeric not between 0 and 10 then raise exception 'RPE or minutes out of range';end if;
  if existing_status<>'pending' and not coalesce(overwrite_existing,false) then skipped=skipped+1;continue;end if;
  update public.athlete_sessions set status=(item->>'status')::public.attendance_status,minutes=(item->>'minutes')::integer,rpe=(item->>'rpe')::numeric where athlete_id=a and session_id=sid;
  if not found then raise exception 'Response update denied' using errcode='42501';end if;
  saved=saved+1;
 else
  if not public.can_write_athlete(a) then raise exception 'Athlete permission denied' using errcode='42501';end if;
  changed=null;
  insert into public.wellness_responses(athlete_id,date,sleep_hours,sleep_quality,fatigue,soreness,stress,appetite,weight,comment)
  values(a,(item->>'date')::date,(item->>'sleep_hours')::numeric,(item->>'sleep_quality')::int,(item->>'fatigue')::int,(item->>'soreness')::int,(item->>'stress')::int,(item->>'appetite')::int,(item->>'weight')::numeric,coalesce(item->>'comment',''))
  on conflict(athlete_id,date) do update set sleep_hours=excluded.sleep_hours,sleep_quality=excluded.sleep_quality,fatigue=excluded.fatigue,soreness=excluded.soreness,stress=excluded.stress,appetite=excluded.appetite,weight=excluded.weight,comment=excluded.comment,updated_at=now() where coalesce(overwrite_existing,false) returning id into changed;
  -- Medical pain records are deliberately not replaced by a daily wellness import.
  if changed is null then skipped=skipped+1;else saved=saved+1;end if;
 end if;
end loop;
return jsonb_build_object('saved',saved,'skipped',skipped);
end$$;

commit;
